Signed-off-by: Sven Eckelmann <sven@narfation.org>
Signed-off-by: Simon Wunderlich <sw@simonwunderlich.de>

Here is the root cause:
The bug is caused by integer overflow when computing the allocation length for a global TT response. The function `batadv_tt_prepare_tvlv_global_data()` uses 16-bit unsigned integers (`u16`) for `change_offset` and `tvlv_len`. When the remote originator advertises a large global translation table, the sum of the TT payload length (`*tt_len`) and the VLAN header offset (`change_offset`) can exceed 65535 (U16_MAX), causing the value to wrap modulo 65536. This results in a small `tvlv_len` that is passed to `kmalloc()`, allocating a buffer too small to hold the actual `tt_change` data. Later, when copying data into this undersized buffer, an out-of-bounds write occurs, leading to heap memory corruption.

Here is the patch:
  */
 static u16
 batadv_tt_prepare_tvlv_global_data(struct batadv_orig_node *orig_node,
 				   struct batadv_tvlv_tt_data **tt_data,
 				   struct batadv_tvlv_tt_change **tt_change,
 				   s32 *tt_len)
 {
 	u16 num_vlan = 0;
 	u16 num_entries = 0;
-	u16 change_offset;
-	u16 tvlv_len;
+	u16 tvlv_len = 0;
+	unsigned int change_offset;
 	struct batadv_tvlv_tt_vlan_data *tt_vlan;
 	struct batadv_orig_node_vlan *vlan;
 	u8 *tt_change_ptr;

 	spin_lock_bh(&orig_node->vlan_list_lock);
 	hlist_for_each_entry(vlan, &orig_node->vlan_list, list) {
 		num_vlan++;
 		num_entries += atomic_read(&vlan->tt.num_entries);
 	}

 	change_offset = struct_size(*tt_data, vlan_data, num_vlan);

 	/* if tt_len is negative, allocate the space needed by the full table */
 	if (*tt_len < 0)
 		*tt_len = batadv_tt_len(num_entries);

+	if (change_offset > U16_MAX || *tt_len > U16_MAX - change_offset) {
+		*tt_len = 0;
+		goto out;
+	}
+
 	tvlv_len = *tt_len;
 	tvlv_len += change_offset;

 	*tt_data = kmalloc(tvlv_len, GFP_ATOMIC);
 	if (!*tt_data) {
 		*tt_len = 0;
 		goto out;
 	}

 	(*tt_data)->flags = BATADV_NO_FLAGS;
 	(*tt_data)->ttvn = atomic_read(&orig_node->last_ttvn);
 	(*tt_data)->num_vlan = htons(num_vlan);

 	tt_vlan = (*tt_data)->vlan_data;
 	hlist_for_each_entry(vlan, &orig_node->vlan_list, list) {
 		tt_vlan->vid = htons(vlan->vid);
 		tt_vlan->crc = htonl(vlan->tt.crc);
 		tt_vlan->reserved = 0;

 		tt_vlan++;
 	}

 	tt_change_ptr = (u8 *)*tt_data + change_offset;
 	*tt_change = (struct batadv_tvlv_tt_change *)tt_change_ptr;

 out:
 	spin_unlock_bh(&orig_node->vlan_list_lock);
 	return tvlv_len;
 }



